#include <LVUI/Compiler.h>
#include <iostream>
#include <stdexcept>
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
std::string compile(std::string_view source){auto result=lvui::compile_native(source,{.framework="LVRS"});if(!result)throw std::runtime_error(std::to_string(result.error().line)+":"+std::to_string(result.error().column)+" "+result.error().message);return *result;}
void item(){auto code=compile("Window { HierarchyItem(text: \"Layer\", itemKey: \"image\", itemId: 3, count: 2, indentLevel: 1, selected: true, hasChildItems: false, iconSize: 0) }");check(code.find("lvrs::HierarchyItem::create")!=code.npos&&code.find("value.row.key = \"image\"")!=code.npos&&code.find("value.row.selected = true")!=code.npos,"HierarchyItem did not lower to its retained native control");}
void list(){auto code=compile("import vm Backend\nWindow { HierarchyList(model: vm.model, generatedRowHeight: 17, generatedIndentStep: 12, generatedIconSize: 0, editable: true, autoExpandAncestorsOnActivate: false, onActiveChanged: vm.select) }");check(code.find("lvrs::HierarchyList::create")!=code.npos&&code.find("value.row_height = 17")!=code.npos&&code.find("value.row_extent = value.item.row_height")!=code.npos&&code.find("std::int64_t id, std::size_t index")!=code.npos,"HierarchyList lost its source row metrics or typed activation payload");}
void reactive(){auto code=compile("import vm Backend\nWindow { HierarchyItem(label: vm.label, count: vm.count, expanded: vm.open, selected: vm.selected, width: vm.width, textColorNormal: vm.color, onExpansionChanged: vm.expand) }");check(code.find("component.set_options(value)")!=code.npos&&code.find("lvui::native::integer(")!=code.npos&&code.find("native_bindings->bind")!=code.npos,"Reactive hierarchy inputs were frozen at construction");}
void controller(){auto code=compile("import vm Backend\nWindow { HierarchyList(controller: vm.controller, generatedRowHeight: vm.height, enabled: vm.enabled) }");check(code.find("value.controller =")!=code.npos&&code.find("component.set_options(value)")!=code.npos,"Native controller lifetime or reactive viewport configuration was lost");}
void diagnostics(){for(auto source:{"Window { HierarchyItem(count: 1.5) }","Window { HierarchyItem(height: 0) }","Window { HierarchyItem(iconSize: 257) }","Window { HierarchyItem(text: \"A\", label: \"B\") }","import vm Backend\nWindow { HierarchyList(model: vm.model, controller: vm.controller) }","import vm Backend\nWindow { HierarchyList(model: vm.model) { HierarchyItem() } }","Window { HierarchyList(model: 3) }","Window { HierarchyList(generatedRowHeight: -1) }"}){auto result=lvui::compile_native(source,{.framework="LVRS"});check(!result&&result.error().line>0,"Invalid hierarchy input lost its source diagnostic");}}
void framework(){auto result=lvui::compile_native("Window { HierarchyList() }");check(result&&result->find("lvui::native::NativeHierarchyList::create")!=result->npos&&result->find("lvrs::")==result->npos&&result->find("<LVRS/")==result->npos,"Independent hierarchy list failed or referenced LVRS");}
void slots(){auto code=compile("Window { HStack { Label(id: \"same\")\nHierarchyItem(count: 2, countView: Label(id: \"same\", text: \"Custom\")) } }");check(code.find("lvrs::HierarchyCountFactory{")!=code.npos&&code.find("Hierarchy countView owner retired")!=code.npos&&code.find("lvrs::HierarchyItem factory_input")!=code.npos,"An inline countView did not acquire its own admitted native scope and typed row context");}
void slot_context(){auto code=compile("import class Row lvrs.HierarchyItem\nimport vm Backend\nlet Counter(row: Row, title: String = \"Pick\"): View = VStack { Label(text: vm.describe(row))\nPushButton(row.activate, text: title) }\nWindow { HierarchyItem(count: 2, countView: Counter) }");check(code.find("scope->factory_input = std::move(factory_input)")!=code.npos&&code.find(".describe(")!=code.npos&&code.find("activate")!=code.npos,"A countView lost its typed item, default input or deferred command");}
void slot_forwarding(){auto code=compile("import class Row lvrs.HierarchyItem\nimport vm Backend\nlet Counter(row: Row): View = Label(text: vm.describe(row))\nlet Wrapper(content: View): View = HierarchyItem(count: 2, countView: content)\nWindow { Wrapper(content: Counter) }");check(code.find("lvrs::HierarchyCountFactory{")!=code.npos&&code.find(".describe(")!=code.npos,"A forwarded countView lost the caller's typed content environment");}
void slot_diagnostics(){for(auto source:{"Window { HierarchyItem(countView: 4) }","Window { HierarchyItem(countView: Missing) }","let Contents: [View] = [Label(), Label()]\nWindow { HierarchyItem(countView: Contents) }","let Wrong(row: String): View = Label(text: row)\nWindow { HierarchyItem(countView: Wrong) }","import class Row lvrs.HierarchyItem\nlet Wrong(row: Row, required: String): View = Label(text: required)\nWindow { HierarchyItem(countView: Wrong) }"}){auto result=lvui::compile_native(source,{.framework="LVRS"});check(!result&&result.error().line>0,"An invalid countView signature or root lost its source diagnostic");}}
void delegate(){auto code=compile("import vm Backend\nWindow { HierarchyList(model: vm.model, itemDelegate: HierarchyItem(baseLeftPadding: 4, iconSize: 0)) }");check(code.find("lvrs::HierarchyDelegateFactory{")!=code.npos&&code.find(".create_item(")!=code.npos&&code.find("delegate_context.apply(value)")!=code.npos&&code.find("auto value = std::move(*inherited)")!=code.npos,"A delegate did not inherit typed list state or acknowledge its native product update");}
void delegate_context(){auto code=compile("import class Entry lvrs.HierarchyDelegateContext\nimport class Row lvrs.HierarchyItem\nimport vm Backend\nlet Count(row: Row): View = Label(text: vm.describe(row))\nlet Item(entry: Entry): View = HierarchyItem(label: vm.title(entry), count: 0, countView: Count)\nWindow { HierarchyList(model: vm.model, itemDelegate: Item) }");check(code.find("lvrs::HierarchyDelegateContext factory_input")!=code.npos&&code.find("lvrs::HierarchyItem factory_input")!=code.npos&&code.find("lvrs::HierarchyItem::create(")==code.npos,"Delegate/count contexts were mixed or the native row product was discarded");}
void delegate_forwarding(){auto code=compile("import class Entry lvrs.HierarchyDelegateContext\nimport vm Backend\nlet Item(entry: Entry): View = HierarchyItem(label: vm.title(entry))\nlet Tree(content: View): View = HierarchyList(model: vm.model, itemDelegate: content)\nWindow { Tree(content: Item) }");check(code.find("Hierarchy itemDelegate owner retired")!=code.npos&&code.find(".create_item(")!=code.npos,"A forwarded delegate lost source ownership or root-product construction");}
void delegate_diagnostics(){for(auto source:{"Window { HierarchyList(itemDelegate: Label()) }","Window { HierarchyList(itemDelegate: 4) }","let Wrong(value: String): View = HierarchyItem()\nWindow { HierarchyList(itemDelegate: Wrong) }","Window { HierarchyList(itemDelegate: HierarchyItem(height: 40)) }","Window { HierarchyList(itemDelegate: HierarchyItem(selected: true)) }"}){auto result=lvui::compile_native(source,{.framework="LVRS"});check(!result&&result.error().line>0,"An invalid delegate product or list-owned property escaped its source diagnostic");}}
}
int main(int argc,char** argv){try{const std::string n=argc>1?argv[1]:"item";if(n=="item")item();else if(n=="list")list();else if(n=="reactive")reactive();else if(n=="controller")controller();else if(n=="diagnostics")diagnostics();else if(n=="framework")framework();else if(n=="slots")slots();else if(n=="slot_context")slot_context();else if(n=="slot_forwarding")slot_forwarding();else if(n=="slot_diagnostics")slot_diagnostics();else if(n=="delegate")delegate();else if(n=="delegate_context")delegate_context();else if(n=="delegate_forwarding")delegate_forwarding();else if(n=="delegate_diagnostics")delegate_diagnostics();else throw std::runtime_error("Unknown hierarchy compiler case");std::cout<<"Hierarchy compiler "<<n<<" passed\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
